// === FORMAT RINGKASAN MINGGUAN (recap riwayat + backtest 5 strategi intraday) ===
// ⚠️ GANTI nomor ini dengan nomor WA tujuan kamu (format 62xxxxxxxxxx)
const NOMOR_TUJUAN = 'GANTI-DENGAN-NOMOR-WA';

const BATAS_KARAKTER_WA = 3500;
function splitPesan(pesan, batas = BATAS_KARAKTER_WA) {
  if (pesan.length <= batas) return [pesan];
  const hasil = [];
  let sisa = pesan;
  while (sisa.length > batas) {
    let potong = sisa.lastIndexOf('\n', batas);
    if (potong <= 0) potong = batas;
    hasil.push(sisa.slice(0, potong));
    sisa = sisa.slice(potong);
  }
  if (sisa.length > 0) hasil.push(sisa);
  return hasil;
}

function fmtAngka(angka, digit = 2) {
  if (angka === undefined || angka === null || angka === '') return '-';
  return Number(angka).toLocaleString('id-ID', { maximumFractionDigits: digit });
}

const rawInput = $input.first().json;
const inputHttp = rawInput || {};
const gagal = Boolean(inputHttp.error) || inputHttp.status !== 'success';

if (gagal) {
  const e = inputHttp.error || {};
  const detailError = inputHttp.detail || e.message || e.description || 'Server tidak merespons.';
  const pesan = `⚠️ *Ringkasan mingguan gagal.*\n${detailError}\n\nPeriksa endpoint /v1/rekomendasi/ringkasan-mingguan.`;
  return [{ json: { pesan_wa: pesan, to: NOMOR_TUJUAN } }];
}

const data = inputHttp.data || inputHttp;
const periode = data.periode || {};
const recap = data.recap_mingguan || {};
const bt = data.backtest || {};

let t = `📊 *RINGKASAN MINGGUAN*\n`;
t += `━━━━━━━━━━━━━━━━━━━━\n`;
if (periode.tanggal_awal && periode.tanggal_akhir) {
  t += `🗓️ ${periode.tanggal_awal} s.d ${periode.tanggal_akhir} (${periode.jumlah_hari_riwayat} hari digest)\n\n`;
} else {
  t += `🗓️ ${periode.jumlah_hari_riwayat} hari digest\n\n`;
}

// --- RECAP MOST ACTIVE ---
const sahamTop = recap.saham_teratas_most_active || [];
t += `🔥 *SAHAM TERAKTIF MINGGU INI*\n`;
if (sahamTop.length === 0) {
  t += `_Belum ada riwayat digest (aktifkan KV/Upstash, atau tunggu notifikasi pagi)._`;
} else {
  sahamTop.slice(0, 8).forEach((s, i) => {
    const pct = s.rata_pct_change_hari !== null && s.rata_pct_change_hari !== undefined
      ? ` (rata ${s.rata_pct_change_hari > 0 ? '+' : ''}${s.rata_pct_change_hari}%)` : '';
    t += `${i + 1}. *${s.ticker}* — ${s.jumlah_hari_muncul}x${pct}\n`;
  });
}

// --- RECAP PER STRATEGI ---
const perStr = recap.per_strategi_intraday || [];
if (perStr.length > 0) {
  t += `\n⚡ *STRATEGI INTRADAY (dari riwayat)*\n`;
  perStr.forEach((s) => {
    const picks = (s.top_picks || []).map((p) => `${p.ticker}(${p.jumlah_hari}x)`).join(', ');
    t += `📌 *${s.nama}*\n`;
    t += `   Aktif ${s.hari_sinyal_aktif}/${s.hari_total} hari | Skor rata2: ${fmtAngka(s.skor_rata2)}\n`;
    if (picks) t += `   Top: ${picks}\n`;
  });
}

// --- BACKTEST 5 STRATEGI ---
const btStrategi = bt.per_strategi || [];
if (bt.dijalankan && btStrategi.length > 0) {
  t += `\n📉 *BACKTEST 5 STRATEGI* (saham: ${(bt.saham_diuji || []).join(', ')})\n`;
  btStrategi.forEach((s) => {
    t += `• *${s.nama}*: `;
    if (s.tipe === 'per_hari') {
      t += `${fmtAngka(s.total_hari_diuji, 0)} hari diuji | RT ${fmtAngka(s.persen_hari_roundtrip_rata2)}% | Eksp/hari ${fmtAngka(s.ekspektasi_per_hari_rata2, 3)}%\n`;
    } else {
      t += `${fmtAngka(s.total_transaksi, 0)} trx | Win ${fmtAngka(s.win_rate_gabungan_persen)}% | Ret/trx ${fmtAngka(s.rata_rata_return_per_transaksi_persen)}%\n`;
    }
  });
  if (bt.catatan) t += `\n_${bt.catatan}_`;
}

// --- PERINGATAN ---
if (data.peringatan_riwayat) t += `\n⚠️ ${data.peringatan_riwayat}\n`;

t += `\n💡 *Aksi:* ketik *scan <TICKER> strategi* untuk detail per saham, atau *scan riwayat* untuk snapshot harian.`;
t += `\n📌 _Recap dari digest harian; backtest = sanity-check (data 60 hari), bukan validasi final._`;

return splitPesan(t).map((p) => ({ json: { pesan_wa: p, to: NOMOR_TUJUAN } }));
